def solve(expr):
    def operate(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def eval_expr(tokens):
        ops = []
        vals = []
        i = 0
        while i < len(tokens):
            if tokens[i] == '(':
                balance = 1
                j = i + 1
                while balance > 0:
                    if tokens[j] == '(':
                        balance += 1
                    elif tokens[j] == ')':
                        balance -= 1
                    j += 1
                vals.append(eval_expr(tokens[i+1:j-1]))
                i = j
            else:
                if tokens[i].isdigit():
                    vals.append(int(tokens[i]))
                else:
                    while ops and precedence(ops[-1]) >= precedence(tokens[i]):
                        vals.append(operate(ops.pop(), vals.pop(), vals.pop()))
                    ops.append(tokens[i])
                i += 1
        while ops:
            vals.append(operate(ops.pop(), vals.pop(), vals.pop()))
        return vals[0]

    return eval_expr(list(expr))

# Example usage:
# print(solve("3+2*2"))
# print(solve("3/2"))
# print(solve("3+5/2"))
